      { w: '葉緑体', d: '光合成の場となる細胞小器官' },
      { w: 'ミトコンドリア', d: '呼吸の場となる細胞小器官' },
      { w: '化学エネルギー', d: '物質の中にたくわえられたエネルギー' },
      { w: '共生説', d: 'ミトコンドリアと葉緑体が取りこまれた原核生物に由来する説' },
      { w: 'シアノバクテリア', d: '光合成をする原核生物。葉緑体の起源' },
      { w: '燃焼', d: '有機物が一気に酸素と反応し熱と光を出すこと' }
